/**
 * How each of the eight batting / bowling attributes ages relative to its discipline. The parameters live in
 * attribute-tilt-model.ts (generated by packages/ratings/src/analysis/attribute-tilts.py); this file is the lookup.
 *
 * Player.progress() draws one change per discipline and adds `attributeTilt(attr, age, gender)` to each attribute's share
 * of it. Weighted by the discipline's attribute weights the tilts sum to zero at every age, so the discipline overall
 * moves as the fitted progression model says and only the mix between attributes shifts (running fades, battingIQ holds,
 * clutch grows with experience, as far as the data show: docs/RATINGS-PIPELINE.md, "Per-attribute age curves").
 */

import { ATTRIBUTE_TILT, type TiltedAttribute } from "./attribute-tilt-model.js";
import { interp, type ProgressionGender } from "./progression.js";

export type { TiltedAttribute };

/** The weights of the attributes in the discipline overalls (calculateBattingOverall / calculateBowlingOverall) */
export const TILT_WEIGHTS: Record<TiltedAttribute, number> = {
  battingIQ: 0.30, timing: 0.30, power: 0.35, running: 0.05,
  wicketTaking: 0.55, economy: 0.20, accuracy: 0.10, clutch: 0.15,
};

/** Points a season added to an attribute's share of its discipline's change, for a player who will be `ageNext` (age after the coming birthday) */
export function attributeTilt(attr: TiltedAttribute, ageNext: number, gender: ProgressionGender = "male"): number {
  const fit = ATTRIBUTE_TILT[gender][attr];
  return interp(fit.ageNodes, fit.tilt, ageNext);
}
